api.controller = function() {
    // The borrowing ledger header uses server-provided data.
};

sp_widget.css:
.ledger-hero {
  --ledger-ink: #34244e;
  --ledger-muted: #79668f;
  --ledger-purple: #8e6bc5;
  position: relative;
  isolation: isolate;
  box-sizing: border-box;
  width: 100%;
  padding: 30px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,.92);
  border-radius: 26px;
  color: var(--ledger-ink);
  background:
    radial-gradient(ellipse at 90% 0%, rgba(255,255,255,.92), transparent 36%),
    radial-gradient(ellipse at 4% 100%, rgba(203,181,255,.42), transparent 45%),
    linear-gradient(125deg, #eee5ff 0%, #f5edff 56%, #fcecff 100%);
  box-shadow: 0 16px 40px rgba(101,76,143,.09);
  font-family: "Inter", "Segoe UI", Arial, sans-serif;
}

.ledger-hero,
.ledger-hero * {
  box-sizing: border-box;
}

.ledger-topline {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #8064aa;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 2px;
}

.ledger-status-dot {
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  border-radius: 50%;
  background: #77c8a7;
  box-shadow: 0 0 0 4px rgba(119,200,167,.17);
}

.ledger-topline-mark {
  color: #9775d0;
  font-size: 18px;
}

.ledger-main {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(220px, .7fr);
  align-items: center;
  gap: 20px;
  padding: 25px 0 22px;
}

.ledger-copy {
  min-width: 0;
}

.ledger-kicker {
  margin-bottom: 9px;
  color: #8c70b4;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.8px;
}

.ledger-copy h1 {
  margin: 0;
  color: var(--ledger-ink);
  font-size: clamp(27px, 3vw, 39px);
  font-weight: 800;
  letter-spacing: -1.5px;
  line-height: 1.12;
}

.ledger-copy h1 span {
  color: #a27bd4;
  font-size: .75em;
}

.ledger-description {
  max-width: 510px;
  margin: 13px 0 0;
  color: var(--ledger-muted);
  font-size: 14px;
  line-height: 1.8;
}

.ledger-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 11px;
  margin-top: 23px;
}

.ledger-button {
  display: inline-flex;
  min-height: 46px;
  align-items: center;
  justify-content: center;
  gap: 20px;
  padding: 0 17px;
  border: 1px solid rgba(255,255,255,.9);
  border-radius: 14px;
  text-decoration: none !important;
  font-size: 12px;
  font-weight: 700;
  transition: transform .2s ease, box-shadow .2s ease,
              background .2s ease, border-color .2s ease;
}

.ledger-button:hover,
.ledger-button:focus {
  transform: translateY(-3px);
  text-decoration: none !important;
  outline: none;
}

.ledger-button-primary {
  color: #fff !important;
  background: linear-gradient(135deg, #9673c9, #805db7);
  box-shadow: 0 8px 18px rgba(126,91,180,.2);
}

.ledger-button-primary:hover,
.ledger-button-primary:focus {
  color: #fff !important;
  box-shadow: 0 12px 25px rgba(126,91,180,.34);
}

.ledger-button-glass {
  color: #5e487e !important;
  background: rgba(255,255,255,.43);
}

.ledger-button-glass:hover,
.ledger-button-glass:focus {
  color: #4d386c !important;
  background: rgba(255,255,255,.82);
  box-shadow: 0 8px 20px rgba(100,76,140,.1);
}

.ledger-arrow {
  font-size: 16px;
  transition: transform .2s ease;
}

.ledger-button:hover .ledger-arrow {
  transform: translateX(3px);
}

.ledger-art {
  position: relative;
  display: flex;
  min-height: 220px;
  align-items: center;
  justify-content: center;
}

.ledger-art-orbit {
  position: absolute;
  aspect-ratio: 1;
  border: 1px solid rgba(158,126,204,.25);
  border-radius: 50%;
}

.ledger-orbit-one {
  width: 205px;
}

.ledger-orbit-two {
  width: 165px;
}

.ledger-orbit-three {
  width: 125px;
  border-color: rgba(158,126,204,.38);
}

.ledger-book-stack {
  position: relative;
  display: flex;
  width: 112px;
  height: 116px;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255,255,255,.95);
  border-radius: 30px;
  background: rgba(255,255,255,.68);
  box-shadow: 0 18px 40px rgba(119,85,166,.13),
              inset 0 0 0 8px rgba(255,255,255,.27);
  transform: rotate(-4deg);
  transition: transform .3s ease, box-shadow .3s ease;
}

.ledger-hero:hover .ledger-book-stack {
  transform: rotate(0deg) translateY(-3px);
  box-shadow: 0 23px 44px rgba(119,85,166,.19),
              inset 0 0 0 8px rgba(255,255,255,.3);
}

.ledger-book {
  position: absolute;
  width: 34px;
  height: 53px;
  border-radius: 5px 7px 7px 5px;
  box-shadow: 0 6px 12px rgba(65,43,97,.12);
}

.ledger-book-back {
  width: 40px;
  height: 59px;
  background: #b7dfa9;
  transform: translate(-12px, -3px) rotate(-7deg);
}

.ledger-book-left {
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: linear-gradient(145deg, #a88ae5, #8565c5);
  transform: translate(-8px, 3px) rotate(-9deg);
}

.ledger-book-right {
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  background: linear-gradient(145deg, #f1b4dc, #dc8fc8);
  transform: translate(19px, 3px) rotate(4deg);
}

.ledger-book span {
  font-size: 22px;
  font-weight: 800;
}

.ledger-book-sparkle {
  position: absolute;
  z-index: 3;
  top: 21px;
  right: 19px;
  color: #a07bd2;
  font-size: 17px;
}

.ledger-art-caption {
  position: absolute;
  bottom: 0;
  color: #9279b0;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 2px;
}

.ledger-divider {
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(155,123,195,.3), transparent);
}

.ledger-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 15px 0 20px;
}

.ledger-bottom-note,
.ledger-bottom-date {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #8a70ad;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.3px;
}

.ledger-note-star {
  color: #a17ed4;
  font-size: 19px;
}

.ledger-bottom-date {
  font-weight: 500;
  letter-spacing: 0;
  font-size: 11px;
}

.ledger-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
}

.ledger-stat {
  position: relative;
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 13px;
  padding: 17px;
  overflow: hidden;
  border: 1px solid rgba(220,203,246,.8);
  border-radius: 17px;
  background: rgba(255,255,255,.68);
  transition: transform .2s ease, box-shadow .2s ease,
              background .2s ease;
}

.ledger-stat::after {
  position: absolute;
  right: -12px;
  bottom: -27px;
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: rgba(196,171,240,.1);
  content: "";
  pointer-events: none;
}

.ledger-stat:hover {
  transform: translateY(-3px);
  background: rgba(255,255,255,.9);
  box-shadow: 0 9px 22px rgba(109,79,153,.09);
}

.ledger-stat-icon {
  display: flex;
  width: 43px;
  height: 43px;
  flex: 0 0 43px;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  color: #815ac1;
  background: #eadfff;
  font-size: 22px;
}

.ledger-stat-lilac {
  background: #e9e0ff;
}

.ledger-stat-peach {
  color: #b66e31;
  background: #ffead5;
}

.ledger-stat > div:last-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.ledger-stat-label {
  color: #8b75a5;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 1.1px;
}

.ledger-stat strong {
  margin-top: 3px;
  color: #3c2a55;
  font-size: 28px;
  font-weight: 800;
  line-height: 1.2;
}

.ledger-stat small {
  margin-top: 3px;
  color: #8b79a0;
  font-size: 10px;
}

@media (max-width: 760px) {
  .ledger-hero {
    padding: 21px;
    border-radius: 21px;
  }

  .ledger-main {
    grid-template-columns: 1fr;
    gap: 5px;
    padding: 22px 0 16px;
  }

  .ledger-copy h1 {
    font-size: 29px;
  }

  .ledger-art {
    min-height: 170px;
  }

  .ledger-orbit-one {
    width: 165px;
  }

  .ledger-orbit-two {
    width: 135px;
  }

  .ledger-orbit-three {
    width: 105px;
  }

  .ledger-stats {
    grid-template-columns: 1fr;
    gap: 9px;
  }

  .ledger-stat {
    padding: 13px;
  }

  .ledger-bottom {
    align-items: flex-start;
  }

  .ledger-bottom-note {
    font-size: 8px;
    letter-spacing: .8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ledger-hero *,
  .ledger-hero *::before,
  .ledger-hero *::after {
    transition: none !important;
  }
}

sp_widget.script:
(function() {
    data.totalCount = 0;
    data.activeCount = 0;
    data.attentionCount = 0;

    var now = new GlideDateTime();
    var nowMs = now.getNumericValue();
    var dayMs = 86400000;

    data.today = now.getLocalDate().getByFormat("dd MMM yyyy");

    var rental = new GlideRecord("u_student_rental");
    rental.addQuery("u_student", gs.getUserID());
    rental.query();

    while (rental.next()) {
        data.totalCount++;

        var status = (rental.getValue("u_status") || "").toLowerCase();

        if (status === "active") {
            data.activeCount++;

            var dueValue = rental.getValue("u_due_date");

            if (dueValue) {
                var due = new GlideDateTime(dueValue);
                var daysLeft = Math.ceil(
                    (due.getNumericValue() - nowMs) / dayMs
                );

                if (daysLeft <= 2) {
                    data.attentionCount++;
                }
            }
        }
    }
})();
